import{a as h,b as l}from"./chunk-GWRTUTMJ.js";import{g as o,h as r}from"./chunk-AYE462O2.js";import"./chunk-F7QIWDFZ.js";import"./chunk-OAJCKJ4O.js";import{b as d}from"./chunk-S4G4JIK7.js";import"./chunk-OPD2ZK4Z.js";import{Wb as t,db as n,wb as a,xb as e}from"./chunk-5ZVFOZSB.js";var y=(()=>{class i{constructor(){this.project=d("/projects/theses")}static{this.\u0275fac=function(s){return new(s||i)}}static{this.\u0275cmp=n({type:i,selectors:[["app-theses"]],decls:23,vars:0,consts:[[1,"page-container","single-project-page"],["href","assets/theses/master-thesis.pdf","download","Stella_Millwood_Master_Thesis.pdf"],["matButton","tonal"],["href","assets/theses/bachelor-thesis.pdf","download","Stella_Millwood_Bachelor_Thesis.pdf"]],template:function(s,u){s&1&&(a(0,"div",0)(1,"h1"),t(2,"Master Thesis"),e(),a(3,"h2"),t(4,"Abstract"),e(),a(5,"p"),t(6,"This study explores ways of visualizing metadata in virtual reality through means other than text. Specifically, we focus on the metadata of a 3D object as a search result and how these visualizations can support understanding of the object. The study draws on research from the field of information science and is positioned in the domain of cultural heritage. There are few studies about human information interaction in virtual reality or metadata visualization in these environments. However, metadata can be a useful tool in the information seeking search process. Because its visualization should depend on purpose, ways of visualizing metadata other than through text are in need of exploration. This study answers the following question: How can descriptive metadata of a 3D search result object be visualized in VR to support users\u2019 understanding of the object? A research through design approach was employed. Data was collected through interviews about objects with visitors at a museum. These interview data were analyzed using a thematic analysis, and the results of that analysis were triangulated with the objects\u2019 metadata in a database. This triangulation resulted in sets of characteristics and techniques that, as expressed by interviewees, could help them gain an understanding of an object of historical and cultural significance. We then selected a smaller set of characteristics for implementation using a prioritization matrix, and an object to visualize metadata for. Brainstorming sessions generated ways of visualizing these characteristics using relevant techniques. The prototype is a virtual reality experience that allows the user to navigate three layers of information with visualizations of the 3D object\u2019s characteristics. The prototype was interactively demonstrated with four participants and their feedback was documented. The discussion is about the definition of metadata, unforeseen designs, the search process, the role of virtual reality in information seeking, how metadata visualizations can support understanding of an object and whether our do, our choice of using research through design as the approach and the study\u2019s ethical and societal implications and its limitations. We conclude that metadata of a search result as an object in VR can be visualized by segmenting the VR experience into different layers of information, specifying a sequence in which the layers are presented that builds a narrative and provides users with multisensory feedback. We encourage future evaluative and comparative studies."),e(),a(7,"a",1)(8,"button",2)(9,"mat-icon"),t(10,"download"),e(),t(11," Download Master Thesis "),e()(),a(12,"h1"),t(13,"Bachelor Thesis"),e(),a(14,"h2"),t(15,"Abstract"),e(),a(16,"p"),t(17,"This study examines what effect an expert\u2019s (high domain knowledge) search trail has on novices\u2019 (low domain knowledge) benefit for a task of high complexity. Previous studies have examined task complexity and the expert-novice relationship during search. However, the benefit has not yet been extensively studied. Novices are asked to solve a task of high complexity with the optional support of an expert\u2019s search trail. We employ a mixed methods approach and use both quantitative and qualitative data. Methods of data collection include questionnaires and log files. The data are analyzed using search log analysis, charts and a thematic analysis. All novices reused expert terms, but the most commonly reused term did not refer to the task\u2019s complex section. Furthermore, the expert\u2019s search trail was helpful to the novices, but source criticism was challenging, and the need for the search trail diminished during the search process. Additionally, a few novices avoided expert terms, but felt the ones they used were helpful. We conclude that an expert\u2019s search trail is of partial benefit to domain novices. The limitations of the benefit are discussed, and we encourage future work to explore the scope of and reason for these limitations."),e(),a(18,"a",3)(19,"button",2)(20,"mat-icon"),t(21,"download"),e(),t(22," Download Bachelor Thesis "),e()()())},dependencies:[l,h,r,o],encapsulation:2})}}return i})();export{y as ThesesComponent};
